referenceSolutions.javascript:
function bitRibbonsBossReceipt(readings, k) {
  const a=readings; let out=[];
  for(let x of a){let count=0;while(x){x&=x-1;count++;}out.push(count);}
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}

